                if($records.Count -eq 1 -and $records[0].Status -eq 'RebootRequired'){$bootPassed=$false;try{$bootAfter=Get-WsmBootStamp;$bootPassed=($records[0].BootBefore -and $bootAfter -and ([DateTime]::Parse($bootAfter).ToUniversalTime() -gt [DateTime]::Parse([string]$records[0].BootBefore).ToUniversalTime()))}catch{};$checks.Add((Get-WsmLabCheck 'RebootBarrier' $(if($bootPassed){'PASS'}else{'Blocked'}) $id $adapter 'PostBootObserved' '' '' $(if($bootPassed){'A later boot was observed.'}else{'Required reboot is not confirmed.'})))}
