                try{$receipts=@();if($adapter -eq 'ScheduledTask'){$receipts=Get-WsmTaskSecurityReceiptsForSpec $item.MigrationSpec (Get-WsmTaskSecurityOwnershipReceipts $state)};$adapterCheck=Test-WsmAdapterConfiguration $item.MigrationSpec $Phase $receipts;$status='PASS';if(-not $adapterCheck.Passed){$status='FAIL'};$actualHash=Get-WsmHashText ($adapterCheck.Actual | ConvertTo-Json -Depth 20 -Compress);$desiredHash=Get-WsmHashText ($item.MigrationSpec | ConvertTo-Json -Depth 40 -Compress);$hint='Desired spec SHA256='+$desiredHash+'; observed state SHA256='+$actualHash+'; exact native field comparison '+$status+'.';$checks.Add((Get-WsmLabCheck 'AdapterConfiguration' $status $id $adapter 'DesiredSpecAndObservedStateDigests' '' $actualHash $hint))}catch{$failure=Get-WsmLabSafeFailure $_;$checks.Add((Get-WsmLabCheck 'AdapterConfiguration' 'Blocked' $id $adapter $Phase '' '' 'Native read-only adapter inspection failed; inspect the host locally.' $failure.Category $failure.NativeCode $failure.HResult))}
